import React, { useMemo, useState } from 'react';
import { Button } from '@jinx-ui/react';

type ProjectStatus = 'active' | 'warning' | 'over';

interface Project {
  id: string;
  name: string;
  status: ProjectStatus;
  quotaPercent: number;
}

const STATUS_META: Record<ProjectStatus, { label: string; tone: string }> = {
  active: { label: 'Активен', tone: 'success' },
  warning: { label: 'Внимание', tone: 'warning' },
  over: { label: 'Превышен', tone: 'danger' },
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Alpha Redesign', status: 'active', quotaPercent: 42 },
  { id: 'p2', name: 'Beta Migration', status: 'warning', quotaPercent: 78 },
  { id: 'p3', name: 'Gamma Analytics', status: 'over', quotaPercent: 112 },
  { id: 'p4', name: 'Delta Onboarding', status: 'active', quotaPercent: 15 },
  { id: 'p5', name: 'Epsilon Billing', status: 'over', quotaPercent: 101 },
  { id: 'p6', name: 'Zeta Search', status: 'active', quotaPercent: 33 },
  { id: 'p7', name: 'Eta Notifications', status: 'warning', quotaPercent: 85 },
  { id: 'p8', name: 'Theta Reports', status: 'active', quotaPercent: 60 },
  { id: 'p9', name: 'Iota Security', status: 'warning', quotaPercent: 90 },
  { id: 'p10', name: 'Kappa Mobile', status: 'over', quotaPercent: 130 },
  { id: 'p11', name: 'Lambda Infra', status: 'active', quotaPercent: 5 },
  { id: 'p12', name: 'Mu Support', status: 'warning', quotaPercent: 70 },
];

const ALL_STATUSES = Object.keys(STATUS_META) as ProjectStatus[];
const PAGE_SIZE = 5;

function QuotaCircle({ percent, tone }: { percent: number; tone: string }) {
  const size = 40;
  const stroke = 4;
  const radius = (size - stroke) / 2;
  const circumference = 2 * Math.PI * radius;
  const clamped = Math.max(0, Math.min(100, percent));
  const dash = (clamped / 100) * circumference;

  return (
    <div className="jx-quota-circle" role="img" aria-label={`Квота заполнена на ${percent}%`}>
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke="var(--jx-color-border-muted)"
          strokeWidth={stroke}
        />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke={`var(--jx-color-${tone})`}
          strokeWidth={stroke}
          strokeDasharray={`${dash} ${circumference}`}
          strokeLinecap="round"
          transform={`rotate(-90 ${size / 2} ${size / 2})`}
        />
      </svg>
      <span className="jx-quota-circle-label">{percent}%</span>
    </div>
  );
}

export default function ProjectSpendPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(0);

  const removeStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) => prev.filter((s) => s !== status));
    setPage(0);
  };

  const resetFilters = () => {
    setActiveStatuses(ALL_STATUSES);
    setPage(0);
  };

  const filteredProjects = useMemo(
    () => PROJECTS.filter((p) => activeStatuses.includes(p.status)),
    [activeStatuses]
  );

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount - 1);
  const pageItems = filteredProjects.slice(
    safePage * PAGE_SIZE,
    safePage * PAGE_SIZE + PAGE_SIZE
  );

  return (
    <div className="jx-panel jx-panel-spend">
      <div className="jx-panel-header">
        <h2 className="jx-heading">Расход по проектам</h2>
      </div>

      <div className="jx-chip-row" role="group" aria-label="Фильтры по статусу">
        {activeStatuses.length === 0 && (
          <span className="jx-empty-hint">Нет активных фильтров</span>
        )}
        {activeStatuses.map((status) => (
          <span
            key={status}
            className={`jx-chip jx-chip--${STATUS_META[status].tone}`}
          >
            {STATUS_META[status].label}
            <button
              type="button"
              className="jx-chip-remove"
              aria-label={`Убрать фильтр ${STATUS_META[status].label}`}
              onClick={() => removeStatus(status)}
            >
              ×
            </button>
          </span>
        ))}
      </div>

      {filteredProjects.length === 0 ? (
        <div className="jx-empty-state">
          <p className="jx-empty-state-title">Нет проектов по выбранным фильтрам</p>
          <p className="jx-empty-state-description">
            Попробуйте сбросить фильтры, чтобы увидеть все проекты.
          </p>
          <Button variant="secondary" onClick={resetFilters}>
            Сбросить фильтры
          </Button>
        </div>
      ) : (
        <>
          <ul className="jx-list jx-list--spend">
            {pageItems.map((project) => {
              const meta = STATUS_META[project.status];
              return (
                <li key={project.id} className="jx-list-row jx-spend-row">
                  <span className="jx-spend-row-name">{project.name}</span>
                  <QuotaCircle percent={project.quotaPercent} tone={meta.tone} />
                  <span className={`jx-badge jx-badge--${meta.tone}`}>{meta.label}</span>
                </li>
              );
            })}
          </ul>

          <div className="jx-pagination" role="navigation" aria-label="Постраничная навигация">
            <Button
              variant="ghost"
              disabled={safePage === 0}
              onClick={() => setPage((p) => Math.max(0, p - 1))}
            >
              Назад
            </Button>
            <span className="jx-pagination-status">
              Страница {safePage + 1} из {pageCount}
            </span>
            <Button
              variant="ghost"
              disabled={safePage >= pageCount - 1}
              onClick={() => setPage((p) => Math.min(pageCount - 1, p + 1))}
            >
              Далее
            </Button>
          </div>
        </>
      )}
    </div>
  );
}

